mapper.select:

SELECT
    id, job_uid, report_id, report_title_snapshot, title_search_key, source, institution, publish_date,
    theme_tags, industry_tags, company_tags, ticker_tags, author_tags, original_filename, file_path,
    ocr_status, chunk_status, vector_status, ocr_attempt_count, chunk_attempt_count, vector_attempt_count, next_run_at, priority,
    last_error_code, last_error_message, created_at, updated_at
FROM ingest_job
WHERE



            ocr_status = #{status}



            ocr_status = 'SUCCEEDED' AND chunk_status = #{status}



            ocr_status = 'SUCCEEDED' AND chunk_status = 'SUCCEEDED' AND vector_status = #{status}



  AND next_run_at <= #{nextRunAt}

ORDER BY priority DESC, next_run_at ASC, id ASC

LIMIT #{limit}

